using System.Collections.Immutable;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using SingletonDI.Generator;
using Xunit;

namespace SingletonDI.Tests;

/// <summary>
/// Tests for property name resolution in SingletonDI.Generator.
/// These tests verify that property names are correctly generated by compiling code
/// that uses the generated properties. If the code compiles successfully, the properties
/// exist with the correct names and types.
/// </summary>
public class PropertyNameResolverTests
{
    #region TC01-TC03: Basic Scenarios

    /// <summary>
    /// TC01: Single provider without conflict.
    /// Expected property name: {ShortName}Instance (e.g., MyServiceInstance)
    /// </summary>
    [Fact]
    public void TC01_SingleProvider_NoConflict_GeneratesShortNameProperty()
    {
        const string SOURCE = """
            using SingletonDI.Attributes;

            namespace MyApp.Services
            {
                [SingletonDIProvide]
                public class MyService
                {
                    public void DoWork() { }
                }

                [SingletonDIConsume(typeof(MyService))]
                public partial class Consumer
                {
                    public void UseService()
                    {
                        MyService service = MyServiceInstance;
                        service.DoWork();
                    }
                }

                public class DerivedConsumer : Consumer
                {
                    public void UseServiceFromDerived()
                    {
                        MyService service = MyServiceInstance;
                        service.DoWork();
                    }
                }
            }
            """;

        var compilationErrors = CompilationErrors(SOURCE);

        Assert.Empty(compilationErrors);
    }

    /// <summary>
    /// TC02: Single provider with custom property name.
    /// Expected property name: {CustomName} (without Instance suffix)
    /// </summary>
    [Fact]
    public void TC02_SingleProvider_WithCustomName_UsesCustomName()
    {
        const string SOURCE = """
