    /// <summary>
    /// TC10: Custom name matches another provider's ShortName.
    /// Expected: No conflict - custom name takes precedence
    /// </summary>
    [Fact]
    public void TC10_CustomName_MatchesOtherProviderShortName_NoConflict()
    {
        const string SOURCE = """
            using SingletonDI.Attributes;

            namespace NamespaceA
            {
                [SingletonDIProvide("ServiceB")]
                public class ServiceA { }
            }

            namespace NamespaceB
            {
                [SingletonDIProvide]
                public class ServiceB { }
            }

            namespace ConsumerNamespace
            {
                [SingletonDIConsume(typeof(NamespaceA.ServiceA), typeof(NamespaceB.ServiceB))]
                public partial class Consumer
                {
                    public void UseServices()
                    {
                        // ServiceA uses custom name "ServiceB"
                        NamespaceA.ServiceA a = ServiceB;
                        // ServiceB uses its ShortName with Instance suffix
                        NamespaceB.ServiceB b = ServiceBInstance;
                    }
                }

                public class DerivedConsumer : Consumer
                {
                    public void UseServicesFromDerived()
                    {
                        NamespaceA.ServiceA a = ServiceB;
                        NamespaceB.ServiceB b = ServiceBInstance;
                    }
                }
            }
            """;

        var compilationErrors = CompilationErrors(SOURCE);

        Assert.Empty(compilationErrors);
    }

